def has_cycle(graph):
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {n: WHITE for n in graph}
    for nbrs in graph.values():
        for n in nbrs:
            color.setdefault(n, WHITE)

    def dfs(n):
        color[n] = GRAY
        for m in graph.get(n, []):
            if color[m] == GRAY:
                return True
            if color[m] == WHITE and dfs(m):
                return True
        color[n] = BLACK
        return False

    return any(dfs(n) for n, c in color.items() if c == WHITE)
```

Gray back-edge means a cycle.

